// Formats a Date as YYYY-MM-DD.
function formatDate(d) {
  if (!(d instanceof Date) || Number.isNaN(d.getTime())) return 'n/a-date';
  return d.toISOString().slice(0, 10);
}
module.exports = { formatDate };

