const fs = require('fs');
if (!fs.existsSync('build.config.json')) {
  console.error('build failed: build.config.json is missing. Create it with {"target": "web"}.');
  process.exit(1);
}
const c = JSON.parse(fs.readFileSync('build.config.json', 'utf8'));
if (c.target !== 'web') { console.error('build failed: target must be "web"'); process.exit(1); }
console.log('BUILD OK');
